// @ts-strict-ignore
import { Reducer } from "react";
import { uniqueId } from "lodash-es";
import {
  Direction,
  SeasonPassAction,
  SeasonPassActionType,
  SeasonPassPurchaseState,
  SeasonPassPurchaseType,
  SeasonPassStep,
  SeasonPassToPurchase,
  SeasonPassToReactivate,
  VisitorCategory,
} from "@/core/types/state/season-pass-purchase/season-pass-purchase-types";

export const initialStateStepsWithReactivate = [
  SeasonPassStep.QUANTITY,
  SeasonPassStep.REACTIVATE,
  SeasonPassStep.SELECT_TYPE,
];

export const initialStateStepsWithoutReactivate = [SeasonPassStep.QUANTITY, SeasonPassStep.SELECT_TYPE];

const SeasonPassPurchaseInitialState: SeasonPassPurchaseState = {
  activeStep: SeasonPassStep.QUANTITY,
  quantity: new Map<VisitorCategory, number>(),
  reactivateQuantity: new Map<VisitorCategory, number>(),
  reactivateCardsInProgress: new Map<string, string>(),
  reactivateCardsCurrentCard: "",
  newSeasonPasses: new Map<string, SeasonPassToPurchase>(),
  reactivateSeasonPasses: new Map<string, SeasonPassToReactivate>(),
};

const getSeasonPassFromQuantity = <T extends SeasonPassPurchaseType>(
  visitorCategory: VisitorCategory,
  quantity: number,
  seasonPassPurchaseType: T,
): Array<Omit<SeasonPassToPurchase, "type"> & { type: T }> => {
  const seasonPasses: Array<Omit<SeasonPassToPurchase, "type"> & { type: T }> = [];
  for (let i = 0; i < quantity; i++) {
    const id = uniqueId(`${seasonPassPurchaseType}-`);
    seasonPasses.push({
      id: id,
      type: seasonPassPurchaseType,
      visitorCategory,
    });
  }
  return seasonPasses;
};

const getNewStep = (state: SeasonPassPurchaseState, direction: Direction): SeasonPassStep => {
  const activeStepIndex = state.steps.findIndex((step) => step === state.activeStep);

  if (direction === "forward") {
    return activeStepIndex === state.steps.length - 1 ? state.activeStep : state.steps[activeStepIndex + 1];
  }
  return activeStepIndex === 0 ? state.activeStep : state.steps[activeStepIndex - 1];
};

const SeasonPassPurchaseReducer: Reducer<SeasonPassPurchaseState, SeasonPassAction> = (state, action) => {
  switch (action.type) {
    case SeasonPassActionType.DEBUG: {
      return { ...state };
    }
    case SeasonPassActionType.PREVIOUS_STEP: {
      const previousStep = getNewStep(state, "back");
      return { ...state, activeStep: previousStep };
    }
    case SeasonPassActionType.NEXT_STEP: {
      const nextStep = getNewStep(state, "forward");
      return { ...state, activeStep: nextStep };
    }
    case SeasonPassActionType.RESET_TO_BEGINING: {
      return {
        ...state,
        activeStep: SeasonPassPurchaseInitialState.activeStep,
        quantity: SeasonPassPurchaseInitialState.quantity,
        reactivateQuantity: SeasonPassPurchaseInitialState.reactivateQuantity,
        newSeasonPasses: SeasonPassPurchaseInitialState.newSeasonPasses,
        reactivateSeasonPasses: SeasonPassPurchaseInitialState.reactivateSeasonPasses,
      };
    }
    case SeasonPassActionType.SET_QUANTITY: {
      const quantityCopy = new Map(state.quantity);
      const { quantity, category } = action.payload;

      if (quantity === 0) {
        quantityCopy.delete(category);
      } else {
        quantityCopy.set(category, quantity);
      }

      return { ...state, quantity: quantityCopy };
    }
    case SeasonPassActionType.SET_QUANTITY_REACTIVATE: {
      const reactivateQuantityCopy = new Map(state.reactivateQuantity);
      reactivateQuantityCopy.set(action.payload.category, action.payload.quantity);

      return { ...state, reactivateQuantity: reactivateQuantityCopy };
    }
    case SeasonPassActionType.SELECT_REACTIVATE_QUANTITY_COMPLETE: {
      // if payload is present, use its values as the new reactivateQuantity
      const reactivateQuantityCopy = new Map(
        action.overrideReactivateQuantity ? action.overrideReactivateQuantity : state.reactivateQuantity,
      );

      const seasonPassesToReactivate: Array<SeasonPassToReactivate> = [];
      for (const [visitorCategory, quantityForCategory] of reactivateQuantityCopy) {
        if (quantityForCategory > 0) {
          const reactivateForCategory = getSeasonPassFromQuantity(visitorCategory, quantityForCategory, "reactivate");
          seasonPassesToReactivate.push(...reactivateForCategory);
        }
      }

      const seasonPassesToPurchase: Array<SeasonPassToPurchase> = [];
      for (const [visitorCategory, quantity] of state.quantity) {
        const reactivateQuantityForCategory = reactivateQuantityCopy.get(visitorCategory) ?? 0;

        const quantityForCategory = quantity - reactivateQuantityForCategory;
        if (quantityForCategory > 0) {
          const passesForCategory = getSeasonPassFromQuantity(visitorCategory, quantityForCategory, "digital");
          seasonPassesToPurchase.push(...passesForCategory);
        }
      }

      return {
        ...state,
        newSeasonPasses: new Map(seasonPassesToPurchase.map((pass) => [pass.id, pass])),
        reactivateSeasonPasses: new Map(seasonPassesToReactivate.map((pass) => [pass.id, pass])),
        activeStep: getNewStep(state, "forward"),
        // Reset reactivateCardsInProgress so that no values are saved if
        // the user goes back from the reactivation step (since we clear the forms)
        reactivateCardsInProgress: new Map(),
      };
    }
    case SeasonPassActionType.CHECK_FOR_REACTIVATE_DUPLICATES: {
      const { cardId, cardNumber } = action.payload;
      const reactivateCardsInProgressCopy = new Map(state.reactivateCardsInProgress);
      reactivateCardsInProgressCopy.set(cardId, cardNumber);

      return {
        ...state,
        reactivateCardsInProgress: reactivateCardsInProgressCopy,
        reactivateCardsCurrentCard: cardId,
      };
    }
    case SeasonPassActionType.COMPLETE_REACTIVATE_PASS: {
      const passesCopy = new Map<string, SeasonPassToReactivate>(state.reactivateSeasonPasses);
      const foundPass = passesCopy.get(action.payload.passId);

      passesCopy.set(foundPass.id, {
        ...foundPass,
        isCardCompleted: true,
        cardInfo: { ...action.payload.completedCard },
      });

      return {
        ...state,
        reactivateSeasonPasses: passesCopy,
      };
    }
    case SeasonPassActionType.CONVERT_REACTIVATE_TO_NEW: {
      const passId = action.payload.passId;
      const reactivatePass = state.reactivateSeasonPasses.get(passId);
      const visitorCategory = reactivatePass.visitorCategory;
      const reactivateSeasonPassesCopy = new Map(state.reactivateSeasonPasses);
      reactivateSeasonPassesCopy.delete(passId);

      const newPass = getSeasonPassFromQuantity(visitorCategory, 1, "digital")[0];

      const newSeasonPassesCopy = new Map([...state.newSeasonPasses, [newPass.id, newPass]]);

      const quantityCopy = new Map(state.quantity);
      quantityCopy.set(visitorCategory, quantityCopy.get(visitorCategory) + 1);

      const reactivateQuantityCopy = new Map(state.reactivateQuantity);
      reactivateQuantityCopy.set(visitorCategory, reactivateQuantityCopy.get(visitorCategory) - 1);

      return {
        ...state,
        reactivateSeasonPasses: reactivateSeasonPassesCopy,
        newSeasonPasses: newSeasonPassesCopy,
        reactivateQuantity: reactivateQuantityCopy,
        quantity: quantityCopy,
      };
    }
    case SeasonPassActionType.CHANGE_NEW_SEASON_PASS_TYPE: {
      const passId = action.payload.passId;
      const newSeasonPassesCopy = new Map(state.newSeasonPasses);
      const pass = newSeasonPassesCopy.get(passId);

      const newPass = {
        ...pass,
        type: action.payload.type,
      };
      newSeasonPassesCopy.set(passId, newPass);
      return {
        ...state,
        newSeasonPasses: newSeasonPassesCopy,
      };
    }
    default: {
      return { ...state };
    }
  }
};

export { SeasonPassPurchaseReducer, SeasonPassPurchaseInitialState };
