import { validateZipNo, validatePhone } from "@/core/helpers/validation-helper";
import { CardInformation } from "@parksandresorts/webapiproxy-types";

/**
 * Validate if card is eligible for reactivation
 */
export function validateReactivateCardResponse(card: CardInformation) {
  const errors: Array<{ field: string; type: "REQUIRED" | "WRONG_FORMAT" }> = [];

  if (!card.cardNumber) {
    errors.push({ field: "cardNumber", type: "REQUIRED" });
  }

  if (!card.firstName) {
    errors.push({ field: "firstName", type: "REQUIRED" });
  }

  if (!card.lastName) {
    errors.push({ field: "lastName", type: "REQUIRED" });
  }

  if (!card.birthDate) {
    errors.push({ field: "birthDate", type: "REQUIRED" });
  }

  if (!card.postalCode) {
    errors.push({ field: "postalCode", type: "REQUIRED" });
  } else if (!validateZipNo(card.postalCode)) {
    errors.push({ field: "postalCode", type: "WRONG_FORMAT" });
  }

  if (!card.email) {
    errors.push({ field: "email", type: "REQUIRED" });
  }

  if (!card.picture) {
    errors.push({ field: "picture", type: "REQUIRED" });
  }

  if (!card.phone) {
    errors.push({ field: "phone", type: "REQUIRED" });
  } else if (!validatePhone(card.phone)) {
    errors.push({ field: "phone", type: "WRONG_FORMAT" });
  }
  return {
    valid: errors.length === 0 ? true : false,
    errors,
  };
}
