const fromProductToGlkProduct = (product: ProductBlockFragment) => {
  return {
    id: Number(product.productData!.glkId),
    friendlySalesNameSwe: product.productName ?? "",
    friendlySalesNameEng: product.productName ?? "",
    friendlyDisplayNameSwe: product.productName ?? "",
    friendlyDisplayNameEng: product.productName ?? "",
    internalName: product.internalTitle,
    priceIncludingVat: 199,
    priceExcludingVat: 159.2,
    vatAmount: 39.8,
    vatFraction: 0.25,
    isBuyable: true,
    stockLevel: 1337,
    minimumQuantity: 1,
    productType: WebshopProductType.STANDARD,
    deliveryTypes: [
      {
        deliveryType: product.productName?.toLowerCase().includes("physical")
          ? DeliveryType.HOME
          : DeliveryType.DIGITAL,
        deliveryProductId: product.productName?.toLowerCase().includes("physical")
          ? SHIPPING_PRODUCT_GLK_ID
          : undefined,
      },
    ],
    metadata: {
      visitorCategory: product.seasonPassVisitorCategory === "Vuxen" ? 2 : 1,
    },
    flags: {},
  } satisfies ProductInformationResponseItem;
};

