const allGlkProducts = allProducts.map((p) => fromProductToGlkProduct(p));

const CustomRenderer: Meta<typeof SeasonPassPurchase>["render"] = (args) => {
  // Mock the CheckoutService.createCart function with some super simple logic that kind of is correct.
  CheckoutService.createCart = async (createCartRequest) => {
    const glkProductsOfCartItems = createCartRequest.items.map((item) => {
      const product = allProducts.find((p) => Number(p.productData?.glkId) === item.productId);
      if (!product) {
        throw new Error(`Product with id ${item.productId} not found`);
      }
      return fromProductToGlkProduct(product);
    });
    const totalSumInclVat = glkProductsOfCartItems.reduce((acc, product) => {
      const price = product.priceIncludingVat;
      return acc + price;
    }, 0);
    const includeShippingProduct = glkProductsOfCartItems.some((p) =>
      p.deliveryTypes.some((d) => d.deliveryType === DeliveryType.HOME),
    );
    const totalSumExclVat = totalSumInclVat / 1.25;
    return {
      cartGuid: "cart-guid-123",
      company: CompanyShortName.GLT,
      culture: "sv-SE",
      cartItems: [
        ...glkProductsOfCartItems.map(
          (item, i) =>
            ({
              cartItemGuid: `cart-item-guid-${item.id}-${i}`,
              productId: item.id,
              productName: item.friendlySalesNameSwe,
              quantity: 1,
              price: {
                amount: {
                  amountIncludingVat: item.priceIncludingVat,
                  vatAmount: item.vatAmount,
                },
                vatPercentage: item.vatFraction * 100,
                unitPriceIncludingVat: item.priceIncludingVat,
              },
              deliveryType: item.deliveryTypes[0].deliveryType,
            }) satisfies CartResponseV2CartItem,
        ),
        ...(includeShippingProduct
          ? [
              {
                cartItemGuid: `shipping-product-id`,
                productId: Number(shippingProduct.productData.glkId),
                productName: shippingProduct.productName,
                quantity: 1,
                price: {
                  amount: {
                    amountIncludingVat: 39,
                    vatAmount: 9.8,
                  },
                  vatPercentage: 25,
                  unitPriceIncludingVat: 39,
                },
                deliveryType: DeliveryType.COLLECT_AT_PARK,
              } satisfies CartResponseV2CartItem,
            ]
          : []),
      ],
      cartPrice: {
        amount: {
          vatAmount: totalSumInclVat - totalSumExclVat,
          amountIncludingVat: totalSumInclVat,
        },
      },
      timestamps: {
        createdOn: "2025-02-25T13:00:13.0597613",
        updatedOn: "2025-02-25T13:14:49.8990232",
        paymentInitializedOn: "2025-02-25T13:00:26.0350882",
        paymentCompletedOn: "2025-02-25T13:14:49.2644864",
        expiresOn: "2025-02-25T13:30:26.0350882",
      },
      discountItems: [],
      voucherCodes: [],
      redeemableValidationResults: [],
      state: CartState.OPEN,
    } satisfies CartResponseV2;
  };
  return (
    <div style={{ display: "flex", flexDirection: "column", gap: "2rem" }}>
      <PageProviders
        currentContentPageData={{
          slugs: { sv: "", en: "" },
          currentLocale: "sv",
        }}
        staticConfigData={{
          eCommerce: {
            preferredPaymentProvider: "Klarna",
            shopServicePaymentSlug: "",
            shopServiceConfirmationSlug: "",
            shopServiceCheckoutSlug: "",
          },
          products: {
            contentfulProducts: allProducts,
            glkProducts: allGlkProducts,
          },
        }}
      >
        <SeasonPassPurchase {...args} />
        <hr />
        <div>
          <h2>👇 Currently in cart 👇</h2>
          <ShopServiceCart />
        </div>
      </PageProviders>
    </div>
  );
};

