export const WithCompleteReactivationData: Story = {
  play: async ({ canvasElement }) => {
    const canvas = within(canvasElement);

    //Wait for 1 seconds to make sure everything has loaded
    await new Promise((resolve) => setTimeout(resolve, 1000));

    //Click one adult and next
    await userEvent.click(canvas.getByTestId("increase-button-Vuxen"));
    await userEvent.click(canvas.getByText(corei18n.t("nextStep")));

    //This is the question about reactivation. Answer yes
    await userEvent.click(canvas.getByText(corei18n.t("yes")));

    //Enter a card number and email to reactivate
    const codeInput = canvas.getByPlaceholderText(corei18n.t("cardNumber")) as HTMLInputElement;
    await userEvent.type(codeInput, "1234567");

    const emailInput = canvas.getByPlaceholderText(corei18n.t("inputPlaceholderEmail")) as HTMLInputElement;
    await userEvent.type(emailInput, "test@test.com");

    //Wait 3 seconds for validation to complete
    await new Promise((resolve) => setTimeout(resolve, 3_000));

    //Press submit
    await userEvent.click(canvas.getByText(corei18n.t("getSeasonPassInfo")));

    //Assert message about missing data is NOT present
    expect(canvas.queryByText(corei18n.t("completeSeasonPassInfo"))).not.toBeInTheDocument();
  },

  args: {
    ...Primary.args,
  },

  render: (args) => {
    CardService.postCard = async (card) => ({
      cardNumber: card.cardNumber,
      email: card.holderEmail!,

      address: "Test",
      birthDate: "2000-01-01",
      cardTypeId: "3",
      city: "Stad",
      isValidForReactivation: true,
      isValidForRefill: true,
      phone: "+46701111111",
      picture: "-some-binary-data-",
      postalCode: "11111",
      willBeReactivated: true,
      firstName: "Boaty",
      lastName: "McBoatface",
    });
    return <CustomRenderer {...args} />;
  },
};

