import { useEffect, useMemo, useState } from "react";
import styles from "./season-pass-select-type.module.less";
import {
  SeasonPassActionType,
  SeasonPassStepBaseProps,
  SeasonPassToPurchase,
  SeasonPassToReactivate,
} from "@/core/types/state/season-pass-purchase/season-pass-purchase-types";
import { PrimaryButton } from "@/core/components/primitives/parks-button/parks-button";
import ReactivatePass from "./components/reactivate-pass";
import { useShopServiceCartContext } from "@/core/contexts";
import { groupBy, sum } from "lodash-es";
import StyledRadioButtons from "@/core/components/primitives/styled-radio-buttons/styled-radio-buttons";
import { RadioOption } from "@/core/components/primitives/radio-buttons/radio-buttons";
import { isNonEmptyArray, CurrencyHelper, throwError } from "@/core/helpers";
import SummaryList from "@/core/components/primitives/summary-list/summary-list";
import RichText, { RichTextType } from "@/core/components/primitives/rich-text/rich-text";
import { useTranslation } from "react-i18next";
import NotificationHelper from "@/core/helpers/notification-helper";
import ToggleSwitch from "@/core/components/primitives/toggle-switch/toggle-switch";
import { CartRequestCartItem } from "@parksandresorts/webapiproxy-types";
import { useMutation } from "@tanstack/react-query";
import { NormalizedProduct } from "@/core/hooks/product-hooks";
import { TFunction } from "i18next";
import { LabelKey } from "@/core/labels/i18n";

type SeasonPassSelectTypeProps = {
  newSeasonPasses: Map<string, SeasonPassToPurchase>;
  reactivateSeasonPasses: Map<string, SeasonPassToReactivate>;
  isPhysicalPassAvailable: boolean;
  reactivateInstruction: RichTextType | undefined;
  selectPassTypeInstruction: RichTextType | undefined;
  reactivateCardsInProgress: Map<string, string>;
  reactivateCardsCurrentCard: string;
  reactivationProducts: Array<NormalizedProduct>;
  digitalProducts: Array<NormalizedProduct>;
  physicalProducts: Array<NormalizedProduct>;
} & SeasonPassStepBaseProps;

const GROUP_CAP = 20;

const isStateCartReady = (reactivateSeasonPasses: Map<string, SeasonPassToReactivate>): boolean => {
  const isReactivatePassesCartReady =
    reactivateSeasonPasses.size > 0 ? [...reactivateSeasonPasses.values()].every((pass) => pass.isCardCompleted) : true;

  return isReactivatePassesCartReady;
};

const getShopServiceCartItems = (
  newSeasonPasses: Map<string, SeasonPassToPurchase>,
  reactivateSeasonPasses: Map<string, SeasonPassToReactivate>,
  reactivationProducts: Array<NormalizedProduct>,
  digitalProducts: Array<NormalizedProduct>,
  physicalProducts: Array<NormalizedProduct>,
): Array<CartRequestCartItem> => {
  const cartRequestItems = [] as Array<CartRequestCartItem>;
  if (newSeasonPasses.size > 0) {
    for (const { type, visitorCategory } of newSeasonPasses.values()) {
      const productList = type === "digital" ? digitalProducts : physicalProducts;
      const product =
        productList.find((prod) => (prod.glkProduct?.metadata?.visitorCategory ?? 0) === visitorCategory)?.glkProduct ??
        throwError(`GLK product missing for new ${type} pass with category ${visitorCategory}`);

      cartRequestItems.push({
        productId: product.id,
        quantity: 1,
        deliveryType: product.deliveryTypes[0].deliveryType,
      });
    }
  }

  if (reactivateSeasonPasses.size > 0) {
    for (const pass of reactivateSeasonPasses.values()) {
      if (!pass.isCardCompleted) {
        throw new Error("Trying to add reactivate pass to cart that is not completed: " + pass.id);
      }
      const { visitorCategory, cardInfo } = pass;
      const product =
        reactivationProducts.find((prod) => (prod.glkProduct?.metadata?.visitorCategory ?? 0) === visitorCategory)
          ?.glkProduct ?? throwError(`GLK product missing for reactivate pass with category ${visitorCategory}`);

      cartRequestItems.push({
        productId: product.id,
        quantity: 1,
        deliveryType: product.deliveryTypes[0].deliveryType,
        data: {
          cardReactivationV1: {
            cardNumber: parseInt(cardInfo.cardNumber),
          },
          cardHolderInformationV1: {
            dateOfBirth: cardInfo.birthDate,
            firstName: cardInfo.firstName,
            lastName: cardInfo.lastName,
            postalCode: cardInfo.postalCode,
            email: cardInfo.email,
            mobileNumber: cardInfo.phone,
            image: cardInfo.picture,
          },
        },
      });
    }
  }

  return cartRequestItems;
};

type NewSeasonPassListProps = {
  newSeasonPasses: Map<string, SeasonPassToPurchase>;
  digitalProducts: Array<NormalizedProduct>;
  isPhysicalPassAvailable: boolean;
} & SeasonPassStepBaseProps;

const NewSeasonPassList = ({
  newSeasonPasses,
  digitalProducts,
  isPhysicalPassAvailable,
  dispatch,
}: NewSeasonPassListProps) => {
  const { t } = useTranslation();
  const [showIndividualPasses, setShowIndividualPasses] = useState(false);
  const newSeasonPassGroups = groupBy([...newSeasonPasses.values()], "visitorCategory");

  return (
    <div className={styles.newPassListWrapper}>
      {Object.keys(newSeasonPassGroups).map((category) => {
        const seasonPasses = newSeasonPassGroups[category];
        const shouldShowGroupingToggler = seasonPasses.length >= GROUP_CAP;

        return (
          <div className={styles.newPassListInnerWrapper} key={category}>
            {shouldShowGroupingToggler && (
              <div className={styles.toggleSwitchWrapper}>
                <ToggleSwitch
                  label={t("seasonPassToggleSingleMultiPass")}
                  isOn={showIndividualPasses}
                  onClick={() => setShowIndividualPasses(!showIndividualPasses)}
                />
              </div>
            )}
            {seasonPasses.length >= GROUP_CAP && !showIndividualPasses ? (
              <ul className={styles.newPassList}>
                <li key={seasonPasses[0].id}>
                  <NewSeasonPassItem
                    pass={seasonPasses[0]}
                    digitalProducts={digitalProducts}
                    isPhysicalPassAvailable={isPhysicalPassAvailable}
                    dispatch={dispatch}
                    batchIdArray={seasonPasses.map((pass) => pass.id)}
                  />
                </li>
              </ul>
            ) : (
              seasonPasses.map((pass) => {
                return (
                  <ul key={category + pass.id} className={styles.newPassList}>
                    <li key={pass.id}>
                      <NewSeasonPassItem
                        pass={pass}
                        digitalProducts={digitalProducts}
                        isPhysicalPassAvailable={isPhysicalPassAvailable}
                        dispatch={dispatch}
                      />
                    </li>
                  </ul>
                );
              })
            )}
          </div>
        );
      })}
    </div>
  );
};

type NewSeasonPassItemProps = {
  pass: SeasonPassToPurchase;
  digitalProducts: Array<NormalizedProduct>;
  isPhysicalPassAvailable: boolean;
  batchIdArray?: Array<string>;
} & SeasonPassStepBaseProps;

const NewSeasonPassItem = ({
  pass,
  digitalProducts,
  isPhysicalPassAvailable,
  batchIdArray,
  dispatch,
}: NewSeasonPassItemProps) => {
  const { t } = useTranslation();
  const options: Array<RadioOption & { value: SeasonPassToPurchase["type"] }> = [
    {
      label: t("digital"),
      value: "digital",
      id: "digital-" + pass.id,
    },
  ];

  if (isPhysicalPassAvailable) {
    options.push({
      label: t("physical"),
      value: "physical",
      id: "physical-" + pass.id,
    });
  }

  const onChangeType = (name: string, value: string) => {
    const passIds = batchIdArray ?? [pass.id];
    for (const passId of passIds) {
      dispatch({
        type: SeasonPassActionType.CHANGE_NEW_SEASON_PASS_TYPE,
        payload: { passId: passId, type: value as SeasonPassToPurchase["type"] },
      });
    }
  };

  // we don't want the product name to change if the user changes between digital/physical, and since digital is always available we use that to get the product name
  const productName = digitalProducts.find(
    (product) => (product.glkProduct?.metadata?.visitorCategory ?? 0) === pass.visitorCategory,
  )?.name;

  return (
    <div className={styles.newPassWrapper}>
      <h6>{batchIdArray ? `${t("seasonPassChooseForAll")} ${productName}` : productName}</h6>
      <StyledRadioButtons options={options} name={"pass-" + pass.id} onChange={onChangeType} value={pass.type} />
    </div>
  );
};

const summaryFromPasses = (
  passes: Array<SeasonPassToReactivate | SeasonPassToPurchase>,
  products: Array<NormalizedProduct>,
  t: TFunction,
  categoryLabel: LabelKey,
) => {
  const summaryItems = [...passes].map((pass) => {
    const product =
      products.find((prod) => (prod.glkProduct?.metadata?.visitorCategory ?? 0) === pass.visitorCategory) ??
      throwError("Product not found for reactivate pass");
    return {
      title: product.name,
      price: CurrencyHelper.formatToSek(product.glkProduct?.priceIncludingVat ?? 0),
      actualPrice: product.glkProduct?.priceIncludingVat ?? 0,
    };
  });

  const priceSum = sum(summaryItems.map((item) => item.actualPrice));

  return {
    category: t(categoryLabel),
    quantity: t("pieces", { count: summaryItems.length }),
    sumPrice: CurrencyHelper.formatToSek(priceSum),
    summaryItems: summaryItems,
    actualSumPrice: priceSum,
  };
};

const SeasonPassSelectType = ({
  reactivateSeasonPasses,
  newSeasonPasses,
  isPhysicalPassAvailable,
  reactivateInstruction,
  selectPassTypeInstruction,
  reactivateCardsInProgress,
  reactivateCardsCurrentCard,
  reactivationProducts,
  digitalProducts,
  physicalProducts,
  dispatch,
}: SeasonPassSelectTypeProps) => {
  const { t } = useTranslation();
  const canAddPassesToCart = isStateCartReady(reactivateSeasonPasses);
  const { addMultipleCartItems: addMultipleCartItemsMutation } = useShopServiceCartContext();

  const {
    mutate: addToShopServiceCartContext,
    isPending: addMultipleCartItemsPending,
    error: addMultipleCartItemsError,
    data: addMultipleCartItemsData,
  } = useMutation({ mutationFn: addMultipleCartItemsMutation });

  const isAddingToCart = addMultipleCartItemsPending;

  useEffect(() => {
    if (addMultipleCartItemsData) {
      dispatch({ type: SeasonPassActionType.RESET_TO_BEGINING });
      NotificationHelper.addCartNotification({
        headline: t("addedToCartHeadline"),
        body: t("addedToCartBody"),
      });
    }
  }, [addMultipleCartItemsData, dispatch, t]);

  useEffect(() => {
    if (addMultipleCartItemsError) {
      console.log(addMultipleCartItemsError);
      NotificationHelper.addCartNotification({
        headline: t("somethingWentWrong"),
        body: t("tryAgain"),
      });
    }
  }, [addMultipleCartItemsError, t]);

  const SHIPPING_COST_IN_SEK = +t("shippingCostInSek");

  const reactivatePassesSummary = useMemo(() => {
    return summaryFromPasses([...reactivateSeasonPasses.values()], reactivationProducts, t, "reactivation");
  }, [reactivateSeasonPasses, reactivationProducts, t]);

  const digitalPassesSummary = useMemo(() => {
    return summaryFromPasses(
      [...newSeasonPasses.values()].filter((pass) => pass.type === "digital"),
      digitalProducts,
      t,
      "digital",
    );
  }, [newSeasonPasses, digitalProducts, t]);

  const physicalPassesSummary = useMemo(() => {
    return summaryFromPasses(
      [...newSeasonPasses.values()].filter((pass) => pass.type === "physical"),
      physicalProducts,
      t,
      "physical",
    );
  }, [newSeasonPasses, physicalProducts, t]);

  const summaryPrice = useMemo(() => {
    let price =
      reactivatePassesSummary.actualSumPrice +
      digitalPassesSummary.actualSumPrice +
      physicalPassesSummary.actualSumPrice;
    if (isNonEmptyArray(physicalPassesSummary.summaryItems)) {
      price += SHIPPING_COST_IN_SEK;
    }
    return price;
  }, [reactivatePassesSummary, digitalPassesSummary, physicalPassesSummary, SHIPPING_COST_IN_SEK]);

  const addPassesToCartAndShowNotification = () => {
    const cartItems = getShopServiceCartItems(
      newSeasonPasses,
      reactivateSeasonPasses,
      reactivationProducts,
      digitalProducts,
      physicalProducts,
    );
    addToShopServiceCartContext(cartItems);
  };

  return (
    <div className={styles.wrapper}>
      {reactivateSeasonPasses && reactivateSeasonPasses.size > 0 && (
        <div className={styles.reactivateWrapper}>
          {reactivateInstruction && <RichText richText={reactivateInstruction} />}
          <ul className={styles.reactivateList}>
            {[...reactivateSeasonPasses.values()].map((pass, index) => {
              return (
                <li key={pass.id}>
                  <ReactivatePass
                    pass={pass}
                    index={index}
                    reactivationProducts={reactivationProducts}
                    reactivateCardsInProgress={reactivateCardsInProgress}
                    reactivateCardsCurrentCard={reactivateCardsCurrentCard}
                    dispatch={dispatch}
                  />
                </li>
              );
            })}
          </ul>
        </div>
      )}
      {newSeasonPasses && newSeasonPasses.size > 0 && (
        <div className={styles.newPassesWrapper}>
          {selectPassTypeInstruction && <RichText richText={selectPassTypeInstruction} />}
          <NewSeasonPassList
            newSeasonPasses={newSeasonPasses}
            digitalProducts={digitalProducts}
            isPhysicalPassAvailable={isPhysicalPassAvailable}
            dispatch={dispatch}
          />
        </div>
      )}
      <div className={styles.summaryWrapper}>
        <h4>{t("summary")}</h4>
        {isNonEmptyArray(reactivatePassesSummary.summaryItems) && (
          <SummaryList
            category={reactivatePassesSummary.category}
            summaryItems={reactivatePassesSummary.summaryItems}
            quantity={reactivatePassesSummary.quantity}
            sumPrice={reactivatePassesSummary.sumPrice}
            preExpanded={reactivatePassesSummary.summaryItems.length < GROUP_CAP}
          />
        )}
        {isNonEmptyArray(digitalPassesSummary.summaryItems) && (
          <SummaryList
            category={digitalPassesSummary.category}
            summaryItems={digitalPassesSummary.summaryItems}
            quantity={digitalPassesSummary.quantity}
            sumPrice={digitalPassesSummary.sumPrice}
            preExpanded={digitalPassesSummary.summaryItems.length < GROUP_CAP}
          />
        )}
        {isNonEmptyArray(physicalPassesSummary.summaryItems) && (
          <>
            <SummaryList
              category={physicalPassesSummary.category}
              summaryItems={physicalPassesSummary.summaryItems}
              quantity={physicalPassesSummary.quantity}
              sumPrice={physicalPassesSummary.sumPrice}
              preExpanded={physicalPassesSummary.summaryItems.length < GROUP_CAP}
            />
            <div className={styles.shipping}>
              <div className={styles.summaryLabel}>{t("shipping")}</div>
              <div className={styles.summaryPrice}>{CurrencyHelper.formatToSek(SHIPPING_COST_IN_SEK)}</div>
            </div>
          </>
        )}
        <div className={styles.summaryTotal}>
          <div className={styles.summaryLabel}>{t("total")}</div>
          <div className={styles.summaryPrice}>{CurrencyHelper.formatToSek(summaryPrice)}</div>
        </div>
      </div>

      <div className={styles.buttonWrapper}>
        <PrimaryButton
          complementary={true}
          label={t("back")}
          isDisabled={isAddingToCart}
          onClick={() => dispatch({ type: SeasonPassActionType.PREVIOUS_STEP })}
        />
        <PrimaryButton
          label={isAddingToCart ? `${t("adding")}...` : t("addToCart")}
          isDisabled={!canAddPassesToCart || isAddingToCart}
          onClick={addPassesToCartAndShowNotification}
        />
      </div>
    </div>
  );
};

export default SeasonPassSelectType;
