// @ts-strict-ignore
import { useEffect, useRef, useState, Dispatch, SetStateAction } from "react";
import styles from "./reactivate-pass.module.less";
import BirthDateField from "@/core/components/primitives/birth-date-field/birth-date-field";
import ImageField from "@/core/components/primitives/image-field/image-field";
import InputField from "@/core/components/primitives/input-field/input-field";
import { SecondaryButton } from "@/core/components/primitives/parks-button/parks-button";
import { useForm, buildField, Form, FormField, getInitialForm } from "@/core/helpers/form-builder";
import {
  SeasonPassActionType,
  SeasonPassStepBaseProps,
  SeasonPassToReactivate,
} from "@/core/types/state/season-pass-purchase/season-pass-purchase-types";
import { validateReactivateCardResponse } from "@/core/helpers/season-pass-helper";
import AreaLoader from "@/core/components/primitives/area-loader/area-loader";
import { motion } from "framer-motion";
import { useTranslation } from "react-i18next";
import { Modal } from "@/core/components/primitives/modal/modal";
import { useContentContainerRef } from "@/core/components/primitives/content-container/content-container";
import { MODAL_PORTAL_ID } from "@/core/components/primitives/modal-portal/modal-portal";
import { Translation } from "@/core/labels/i18n";
import { CardService } from "@/core/services/card-service";
import { ReactivatePassInvalidCard } from "./reactivate-pass-invalid-card";
import { NormalizedProduct } from "@/core/hooks/product-hooks";
import { throwError } from "@/core/helpers";
import { CardInformation } from "@parksandresorts/webapiproxy-types";

type ReactivatePassProps = {
  pass: SeasonPassToReactivate;
  index: number;
  reactivationProducts: Array<NormalizedProduct>;
  reactivateCardsInProgress: Map<string, string>;
  reactivateCardsCurrentCard: string;
} & SeasonPassStepBaseProps;

const getCompleteCardInfoForm = (card: CardInformation, t: Translation): Form => {
  const form = getInitialForm();

  form.fields.set(
    "firstName",
    buildField("firstName", {
      label: t("firstName"),
      autoComplete: "given-name",
      isRequired: true,
      value: card.firstName,
    }),
  );
  form.fields.set(
    "lastName",
    buildField("lastName", {
      label: t("lastName"),
      autoComplete: "family-name",
      isRequired: true,
      value: card.lastName,
    }),
  );
  form.fields.set(
    "email",
    buildField("email", {
      label: t("email"),
      autoComplete: "email",
      isRequired: true,
      errorText: t("inputValidationEmail"),
      value: card.email,
    }),
  );
  form.fields.set(
    "phone",
    buildField("phone", {
      label: t("phone"),
      autoComplete: "tel",
      isRequired: true,
      errorText: t("inputValidationPhone"),
      value: card.phone,
    }),
  );
  form.fields.set(
    "postalCode",
    buildField("postalCode", {
      label: t("postalCode"),
      autoComplete: "postal-code",
      isRequired: true,
      errorText: t("inputValidationPostalCode"),
      value: card.postalCode,
    }),
  );
  form.fields.set(
    "birthDate",
    buildField("birthDate", {
      label: t("dateOfBirth"),
      isRequired: true,
      errorText: t("inputValidationDateOfBirth"),
      value: card.birthDate && card.birthDate.length >= 10 ? card.birthDate.substring(0, 10) : "",
    }),
  );
  form.fields.set(
    "picture",
    buildField("picture", {
      label: t("imageID"),
      isRequired: true,
      helperText: t("imageIDHelperText"),
      value: card.picture,
    }),
  );

  return form;
};

const useReactivatePassForm = (index: number) => {
  const { t } = useTranslation();

  const initialForm: Form = {
    fields: new Map<string, FormField>()
      .set(
        "cardNumber",
        buildField("cardNumber", {
          label: t("cardNumber"),
          placeholder: t("cardNumber"),
          type: "INPUT_FIELD",
          isRequired: true,
          fieldId: "card-" + index,
        }),
      )
      .set(
        "email",
        buildField("email", {
          label: t("email"),
          placeholder: t("inputPlaceholderEmail"),
          type: "INPUT_FIELD",
          isRequired: true,
          autoComplete: "email",
          validationType: "EMAIL",
          errorText: t("inputValidationEmail"),
        }),
      ),
  };
  const [form, isFormValid, onChange] = useForm(initialForm);

  return { form, isFormValid, onChange };
};

type CompleteCardFormProps = {
  pass: SeasonPassToReactivate;
  cardNumber: string;
  cardInformation: CardInformation;
  setShowCompleteCardModal: Dispatch<SetStateAction<boolean>>;
  title: string;
} & SeasonPassStepBaseProps;

type ReactivateCardState = "validCard" | "duplicateCard" | "missingFields" | "isNotValidForReactivation" | "notFound";

const CompleteCardForm = ({
  pass,
  cardNumber,
  cardInformation,
  setShowCompleteCardModal,
  dispatch,
  title,
}: CompleteCardFormProps) => {
  const { t } = useTranslation();
  const [form, isFormValid, onChange, , validateForm] = useForm(getCompleteCardInfoForm(cardInformation, t));
  const wrapperElement = useContentContainerRef();

  useEffect(() => {
    validateForm();
  }, [cardInformation]);

  const onClickSave = () => {
    const completedCard: Partial<CardInformation> = {};
    form.fields.forEach((field) => {
      completedCard[field.name] = field.value;
    });

    completedCard.cardNumber = cardNumber;

    if (isFormValid) {
      dispatch({
        type: SeasonPassActionType.COMPLETE_REACTIVATE_PASS,
        payload: {
          passId: pass.id,
          completedCard: completedCard as CardInformation,
        },
      });
    }
  };

  return (
    <Modal
      className={styles.modalWrapper}
      modalTitle="modalTitle"
      portalId={MODAL_PORTAL_ID}
      isOpen={true}
      refWrapperElement={wrapperElement}
      disableInitialFocusInModal={true}
      onClose={() => setShowCompleteCardModal(false)}
      verticalContentPosition="top"
      horizontalContentPosition="center"
    >
      <div className={styles.completeCardFormWrapper}>
        <h4 id="modalTitle">{title}</h4>
        <h5>
          {t("card")} {cardInformation.cardNumber}
        </h5>
        <InputField formField={form.fields.get("firstName")} onChange={onChange} maxLength={50} />
        <InputField formField={form.fields.get("lastName")} onChange={onChange} maxLength={50} />
        <InputField formField={form.fields.get("email")} onChange={onChange} maxLength={75} />
        <InputField formField={form.fields.get("phone")} onChange={onChange} maxLength={50} />
        <InputField formField={form.fields.get("postalCode")} onChange={onChange} maxLength={6} />
        <BirthDateField formField={form.fields.get("birthDate")} onChange={onChange} />
        <ImageField formField={form.fields.get("picture")} onUserChanged={onChange} />
        <SecondaryButton isFullWidth={true} label={t("save")} isDisabled={!isFormValid} onClick={onClickSave} />
        <SecondaryButton
          className={styles.lowerButton}
          complementary={true}
          isFullWidth={true}
          label={t("cancel")}
          onClick={() => setShowCompleteCardModal(false)}
        />
      </div>
    </Modal>
  );
};

const ReactivatePass = ({
  pass,
  index,
  reactivationProducts,
  reactivateCardsInProgress,
  reactivateCardsCurrentCard,
  dispatch,
}: ReactivatePassProps) => {
  const [isLoading, setIsLoading] = useState(false);
  const { form, isFormValid, onChange } = useReactivatePassForm(index);
  const [cardInformation, setCardInformation] = useState<CardInformation>(null);
  const [reactivateCardState, setReactivateCardState] = useState<ReactivateCardState>(null);
  const [showCompleteCardModal, setShowCompleteCardModal] = useState(false);
  const wrapperRef = useRef();
  const { t } = useTranslation();

  useEffect(() => {
    if (reactivateCardState === "missingFields" && pass.isCardCompleted === true) {
      setShowCompleteCardModal(false);
    }
  }, [pass.isCardCompleted]);

  /* CHECK FOR DUPLICATE CARDS (cards with the same card number) */
  useEffect(() => {
    // In case user goes back to previos step
    if (reactivateCardsInProgress.size === 0) {
      return;
    }

    /* If several cards are being reactivated, this effect will run for each cards form.
    By tracking which card was updated (reactivateCardsCurrentCard)
    and checking which card is currently being processed (form.fields.get("cardNumber").fieldId)
    we can make sure that the code only runs once */
    if (form.fields.get("cardNumber").fieldId === reactivateCardsCurrentCard) {
      if (reactivateCardsInProgress.size === 1) {
        getCard();
        return;
      }

      setIsLoading(true);

      /*  Get all other card numbers */
      const uniqueCardNumbers = new Set<string>();
      for (const [cardId, cardNumber] of reactivateCardsInProgress.entries()) {
        if (cardId !== reactivateCardsCurrentCard) {
          uniqueCardNumbers.add(cardNumber);
        }
      }

      /*  Check current card last, to make sure the information about duplicates are displayed on the correct card */
      if (uniqueCardNumbers.has(reactivateCardsInProgress.get(reactivateCardsCurrentCard))) {
        setReactivateCardState("duplicateCard");
        setIsLoading(false);
      } else {
        getCard();
      }
    }
  }, [reactivateCardsInProgress]);

  const onClickGetCard = () => {
    setIsLoading(true);
    dispatch({
      type: SeasonPassActionType.CHECK_FOR_REACTIVATE_DUPLICATES,
      payload: { cardId: form.fields.get("cardNumber").fieldId, cardNumber: form.fields.get("cardNumber").value },
    });
    setIsLoading(false);
  };

  const getCard = () => {
    setIsLoading(true);

    const product =
      reactivationProducts.find((prod) => (prod.glkProduct?.metadata?.visitorCategory ?? 0) === pass.visitorCategory)
        ?.glkProduct ?? throwError("GLK product missing for reactivate pass with category " + pass.visitorCategory);

    CardService.postCard({
      cardNumber: form.fields.get("cardNumber").value,
      holderEmail: form.fields.get("email").value,
      productId: product.id,
    })
      .then((response) => {
        const fixedResponse = {
          ...response,
          isValidForReactivation: response.isValidForReactivation ?? false,
          cardTypeId: response.cardTypeId ?? "",
        };
        const validationResult = validateReactivateCardResponse(fixedResponse);
        if (!response.isValidForReactivation) {
          setReactivateCardState("isNotValidForReactivation");
        } else if (response.isValidForReactivation && !validationResult.valid) {
          // Show fields
          setReactivateCardState("missingFields");
        } else {
          setReactivateCardState("validCard");
          dispatch({
            type: SeasonPassActionType.COMPLETE_REACTIVATE_PASS,
            payload: { passId: pass.id, completedCard: fixedResponse },
          });
        }
        setCardInformation(fixedResponse);
      })
      .catch(() => {
        setReactivateCardState("notFound");
        // Could not find card
      })
      .finally(() => {
        setIsLoading(false);
      });
  };

  const onClickConvertPassToNew = () => {
    dispatch({
      type: SeasonPassActionType.CONVERT_REACTIVATE_TO_NEW,
      payload: { passId: pass.id },
    });
  };

  const showCompleteCardForm =
    !pass.isCardCompleted && reactivateCardState === "missingFields" && cardInformation !== null;

  // Use category label translations based on the visitor category, if there is a matching key in LabelType
  const key = `visitorCategory${pass.visitorCategory}` as const;

  return (
    <div ref={wrapperRef} className={styles.wrapper}>
      <h5>{t(key)}</h5>
      <div className={styles.getCardWrapper}>
        <InputField formField={form.fields.get("cardNumber")} isDisabled={pass.isCardCompleted} onChange={onChange} />
        <InputField
          formField={form.fields.get("email")}
          isDisabled={pass.isCardCompleted}
          onChange={onChange}
          maxLength={75}
        />
        {pass.isCardCompleted ? (
          <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} className={styles.cardIsCompleted}>
            <span className={`${styles.completedIcon} icon-check`}></span>
          </motion.div>
        ) : (
          <SecondaryButton
            complementary={true}
            isDisabled={!isFormValid || isLoading}
            isFullWidth={true}
            onClick={onClickGetCard}
            label={isLoading ? t("getting") : t("getSeasonPassInfo")}
          />
        )}
      </div>

      {isLoading && (
        <div className={styles.loader}>
          <AreaLoader loaderText={t("gettingSeasonPass")} />
        </div>
      )}

      {reactivateCardState === "duplicateCard" && (
        <ReactivatePassInvalidCard
          heading="reactivatePassDuplicateHeading"
          text="reactivatePassDuplicateText"
          firstButtonLabel="tryWithOtherInfo"
          firstButtonOnClick={() => setReactivateCardState(null)}
          secondButtonLabel="convertToNewCard"
          secondButtonOnClick={onClickConvertPassToNew}
        />
      )}

      {reactivateCardState === "isNotValidForReactivation" && (
        <ReactivatePassInvalidCard
          heading="reactivatePassCannotReactivateHeading"
          text="reactivatePassCannotReactivateText"
          firstButtonLabel="tryWithOtherInfo"
          firstButtonOnClick={() => setReactivateCardState(null)}
          secondButtonLabel="convertToNewCard"
          secondButtonOnClick={onClickConvertPassToNew}
        />
      )}

      {reactivateCardState === "notFound" && (
        <ReactivatePassInvalidCard
          heading="reactivatePassNotFoundHeading"
          text="reactivatePassNotFoundText"
          firstButtonLabel="tryAgain"
          firstButtonOnClick={() => setReactivateCardState(null)}
          secondButtonLabel="convertToNewCard"
          secondButtonOnClick={onClickConvertPassToNew}
        />
      )}

      {showCompleteCardForm && (
        <ReactivatePassInvalidCard
          heading="reactivatePassMustCompleteHeading"
          text="reactivatePassMustCompleteText"
          firstButtonLabel="completeSeasonPassInfo"
          firstButtonOnClick={() => setShowCompleteCardModal(true)}
          secondButtonLabel="convertToNewCard"
          secondButtonOnClick={onClickConvertPassToNew}
        />
      )}

      {showCompleteCardForm && showCompleteCardModal && (
        <CompleteCardForm
          pass={pass}
          cardNumber={form.fields.get("cardNumber").value}
          cardInformation={cardInformation}
          setShowCompleteCardModal={setShowCompleteCardModal}
          dispatch={dispatch}
          title={t("completeSeasonPassInfo")}
        />
      )}
    </div>
  );
};

export default ReactivatePass;
