import ServiceHelper from "./service-helper";
import { CardInformation, CardInformationRequest } from "@parksandresorts/webapiproxy-types";

type CardInformationRequestWithProductId = Omit<CardInformationRequest, "templateType">;
type CardInformationRequestWithTemplateType = Omit<CardInformationRequest, "productId">;

/**
 * The autogenerated CardInformaionRequest has productId and templateType as required fields.
 * However, this is not entirely true, since the API only requires one of them
 * If and when the autogenerated types from the API changes, this can be removed
 */
type ModifiedCardInformationRequest = CardInformationRequestWithProductId | CardInformationRequestWithTemplateType;

export const CardService = {
  postCard(data: ModifiedCardInformationRequest): Promise<CardInformation> {
    return ServiceHelper.fetchPost<CardInformation>("card", data);
  },
};
