import { Dispatch } from "react";
import { RichTextType } from "@/core/components";
import { CardInformation, ProductMetadata } from "@parksandresorts/webapiproxy-types";

export type VisitorCategory = Required<ProductMetadata>["visitorCategory"] & (0 | 1 | 2 | 3 | 4);

export type SeasonPassStepBaseProps = {
  dispatch: Dispatch<SeasonPassAction>;
};

export type SeasonPassPurchaseState = {
  steps?: Array<SeasonPassStep>;
  activeStep: SeasonPassStep;
  quantity: Map<VisitorCategory, number>;
  reactivateQuantity: Map<VisitorCategory, number>;
  newSeasonPasses: Map<string, SeasonPassToPurchase>;
  reactivateSeasonPasses: Map<string, SeasonPassToReactivate>;
  reactivateCardsInProgress?: Map<string, string>;
  reactivateCardsCurrentCard: string;
};

export enum SeasonPassActionType {
  DEBUG = "DEBUG",
  PREVIOUS_STEP = "PREVIOUS_STEP",
  NEXT_STEP = "NEXT_STEP",
  RESET_TO_BEGINING = "RESET_TO_BEGINING",
  SET_QUANTITY = "SET_QUANTITY",
  SET_QUANTITY_REACTIVATE = "SET_QUANTITY_REACTIVATE",
  SELECT_REACTIVATE_QUANTITY_COMPLETE = "SELECT_REACTIVATE_QUANTITY_COMPLETE",
  CHECK_FOR_REACTIVATE_DUPLICATES = "CHECK_FOR_REACTIVATE_DUPLICATES",
  COMPLETE_REACTIVATE_PASS = "COMPLETE_REACTIVATE_PASS",
  CONVERT_REACTIVATE_TO_NEW = "CONVERT_REACTIVATE_TO_NEW",
  CHANGE_NEW_SEASON_PASS_TYPE = "CHANGE_NEW_SEASON_PASS_TYPE",
}

export enum SeasonPassStep {
  QUANTITY = "QUANTITY",
  REACTIVATE = "REACTIVATE",
  SELECT_TYPE = "SELECT_TYPE",
}

export type SeasonPassPurchaseType = "digital" | "physical" | "reactivate";

export type Direction = "forward" | "back";

export type SeasonPassAction =
  | { type: SeasonPassActionType.DEBUG; payload: unknown }
  | { type: SeasonPassActionType.PREVIOUS_STEP }
  | { type: SeasonPassActionType.NEXT_STEP }
  | { type: SeasonPassActionType.RESET_TO_BEGINING }
  | { type: SeasonPassActionType.SET_QUANTITY; payload: { category: VisitorCategory; quantity: number } }
  | { type: SeasonPassActionType.SET_QUANTITY_REACTIVATE; payload: { category: VisitorCategory; quantity: number } }
  | {
      type: SeasonPassActionType.SELECT_REACTIVATE_QUANTITY_COMPLETE;
      overrideReactivateQuantity?: Map<VisitorCategory, number>;
    }
  | {
      type: SeasonPassActionType.CHECK_FOR_REACTIVATE_DUPLICATES;
      payload: { cardId: string; cardNumber: string };
    }
  | { type: SeasonPassActionType.COMPLETE_REACTIVATE_PASS; payload: { passId: string; completedCard: CardInformation } }
  | { type: SeasonPassActionType.CONVERT_REACTIVATE_TO_NEW; payload: { passId: string } }
  | {
      type: SeasonPassActionType.CHANGE_NEW_SEASON_PASS_TYPE;
      payload: { passId: string; type: SeasonPassToPurchase["type"] };
    };

export type SeasonPassVisitorCategory = {
  category: VisitorCategory;
  pricePerUnitText: string;
};

export type SeasonPassToPurchase = {
  id: string;
  type: Exclude<SeasonPassPurchaseType, "reactivate">;
  visitorCategory: VisitorCategory;
};

export type SeasonPassToReactivate = Omit<SeasonPassToPurchase, "type"> & {
  type: "reactivate";
} & (
    | {
        cardInfo: CardInformation;
        isCardCompleted: true;
      }
    | {
        cardInfo?: undefined;
        isCardCompleted?: false;
      }
  );

export type SeasonPassTexts = {
  description: RichTextType;
  reactivateDescription: RichTextType;
  reactivateInstruction: RichTextType;
  selectPassTypeInstruction: RichTextType;
};
