import EventAggregator from "@/core/helpers/event-aggregator";
import { INotification } from "@/core/types/notifications/notifications";
import { ADD_NOTIFICATION } from "@/core/components/primitives/notification-center/constants/actions";
import { ADD_TO_CART_NOTIFICATION } from "@/core/components/primitives/notification-center/constants/notification-types";
import { TIME_PERSISTENT } from "@/core/components/primitives/notification-center/constants/time-types";

class NotificationHelper {
  addNotification(notification: Omit<INotification, "id">): void {
    EventAggregator.publish(ADD_NOTIFICATION, {
      notificationType: notification.notificationType,
      headline: notification.headline,
      body: notification.body,
      displayTime: notification.displayTime,
    });
  }

  addCartNotification(notification: Omit<INotification, "id">): void {
    EventAggregator.publish(ADD_NOTIFICATION, {
      notificationType: ADD_TO_CART_NOTIFICATION,
      headline: notification.headline,
      body: notification.body,
      displayTime: TIME_PERSISTENT,
    });
  }
}

const helper = new NotificationHelper();
export default helper;
