import styles from "./season-pass-quantity.module.less";
import {
  SeasonPassActionType,
  SeasonPassStepBaseProps,
  SeasonPassVisitorCategory,
  VisitorCategory,
} from "@/core/types/state/season-pass-purchase/season-pass-purchase-types";
import QuantitySelectorStyled from "@/core/components/primitives/quantity-selector-styled/quantity-selector-styled";
import RichText, { RichTextType } from "@/core/components/primitives/rich-text/rich-text";
import { PrimaryButton } from "@/core/components/primitives/parks-button/parks-button";
import { useTranslation } from "react-i18next";
import InputField from "@/core/components/primitives/input-field/input-field";
import ExpandContent from "@/core/components/primitives/expand-content/expand-content";

type SeasonPassQuantityProps = {
  description: RichTextType | undefined;
  visitorCategories: Array<SeasonPassVisitorCategory>;
  quantity: Map<VisitorCategory, number>;
  hasReactivationProducts: boolean;
  showLargerGroupInputField?: boolean;
} & SeasonPassStepBaseProps;

const SeasonPassQuantity = ({
  description,
  visitorCategories,
  quantity,
  hasReactivationProducts,
  showLargerGroupInputField,
  dispatch,
}: SeasonPassQuantityProps) => {
  const { t } = useTranslation();

  const onClickNextStep = () => {
    if (hasReactivationProducts) {
      dispatch({ type: SeasonPassActionType.NEXT_STEP });
    } else {
      const noReactivateQuantity = new Map([...quantity].map(([category]) => [category, 0]));
      dispatch({
        type: SeasonPassActionType.SELECT_REACTIVATE_QUANTITY_COMPLETE,
        overrideReactivateQuantity: noReactivateQuantity,
      });
    }
  };

  const isNextStepButtonDisabled =
    quantity.size > 0 ? [...quantity.values()].every((quantity) => quantity === 0) : true;

  return (
    <div>
      {description && <RichText richText={description} />}
      <div>
        {visitorCategories.map((category) => {
          const label = t(`visitorCategory${category.category}`);
          return (
            <div key={category.category} className={styles.inputWrapper}>
              <QuantitySelectorStyled
                quantity={quantity.get(category.category) ?? 0}
                minQuantity={0}
                maxQuantity={999}
                label={label}
                sublabel={category.pricePerUnitText}
                parentClassName={styles.quantitySelector}
                onQuantityChange={(newQuantity) => {
                  dispatch({
                    type: SeasonPassActionType.SET_QUANTITY,
                    payload: {
                      category: category.category,
                      quantity: newQuantity,
                    },
                  });
                }}
              />
              {showLargerGroupInputField && (
                <>
                  <ExpandContent
                    buttonPosition="top"
                    showMoreLabelOverride={t("seasonPassGroupInputLabelShowMore")}
                    showLessLabelOverride={t("seasonPassGroupInputLabelShowLess")}
                    buttonType="ghost"
                  >
                    <InputField
                      label={`${t("amount")} ${label}`}
                      additionalText={category.pricePerUnitText}
                      value={quantity.get(category.category)?.toString() ?? ""}
                      placeholder="0"
                      inputMode="numeric"
                      maxLength={3}
                      className={styles.quantityInput}
                      onChange={(name, newQuantity) => {
                        const newQuantityInt = parseInt(newQuantity) || 0; // Prevents to get NaN
                        dispatch({
                          type: SeasonPassActionType.SET_QUANTITY,
                          payload: {
                            category: category.category,
                            quantity: newQuantityInt,
                          },
                        });
                      }}
                    />
                  </ExpandContent>
                </>
              )}
            </div>
          );
        })}
      </div>
      <div className={styles.buttonWrapper}>
        <PrimaryButton
          isFullWidth={true}
          label={t("nextStep")}
          isDisabled={isNextStepButtonDisabled}
          onClick={onClickNextStep}
        />
      </div>
    </div>
  );
};

export default SeasonPassQuantity;
