import { Dispatch, SetStateAction, useEffect, useState } from "react";
import styles from "./season-pass-reactivate.module.less";
import {
  SeasonPassActionType,
  SeasonPassStepBaseProps,
  SeasonPassVisitorCategory,
  VisitorCategory,
} from "@/core/types/state/season-pass-purchase/season-pass-purchase-types";
import { PrimaryButton, SecondaryButton } from "@/core/components/primitives/parks-button/parks-button";
import QuantitySelectorStyled from "@/core/components/primitives/quantity-selector-styled/quantity-selector-styled";
import { isNonEmptyArray } from "@/core/helpers";
import RichText, { RichTextType } from "@/core/components/primitives/rich-text/rich-text";
import { useTranslation } from "react-i18next";

type SeasonPassReactivateProps = {
  visitorCategories: Array<SeasonPassVisitorCategory>;
  reactivateQuantity: Map<VisitorCategory, number>;
  quantity: Map<VisitorCategory, number>;
  reactivateDescription: RichTextType | undefined;
} & SeasonPassStepBaseProps;

type ReactivateCardPromptProps = {
  setShowSelectReactivate: Dispatch<SetStateAction<boolean>>;
  quantity: Map<VisitorCategory, number>;
} & SeasonPassStepBaseProps;

type SelectCardsToReactivateProps = {
  visitorCategories: Array<SeasonPassVisitorCategory>;
  reactivateQuantity: Map<VisitorCategory, number>;
  quantity: Map<VisitorCategory, number>;
} & SeasonPassStepBaseProps;

const ReactivateCardPrompt = ({ setShowSelectReactivate, quantity, dispatch }: ReactivateCardPromptProps) => {
  const { t } = useTranslation();

  const onClickNoCardForReactivation = () => {
    const noReactivateQuantity = new Map([...quantity].map(([category]) => [category, 0]));
    dispatch({
      type: SeasonPassActionType.SELECT_REACTIVATE_QUANTITY_COMPLETE,
      overrideReactivateQuantity: noReactivateQuantity,
    });
  };

  const onClickShowSelectReactivate = () => {
    // Only a single card is being bought. We do not need to select how many to reactivate
    const [[firstCategory, firstQuantity]] = quantity.entries();
    if (quantity.size === 1 && firstQuantity === 1) {
      dispatch({
        type: SeasonPassActionType.SELECT_REACTIVATE_QUANTITY_COMPLETE,
        overrideReactivateQuantity: new Map([[firstCategory, 1]]),
      });
    } else {
      setShowSelectReactivate(true);
    }
  };

  return (
    <>
      <div className={styles.reactivatePromptWrapper}>
        <h4 data-contentful-label-id="reactivatePromptHeading">{t("reactivatePromptHeading")}</h4>
        <div className={`${styles.buttonWrapper} ${styles.margin}`}>
          <SecondaryButton complementary={true} label={t("no")} onClick={onClickNoCardForReactivation} />
          <SecondaryButton label={t("yes")} onClick={onClickShowSelectReactivate} />
        </div>
      </div>
      <div className={styles.backButtonWrapper}>
        <PrimaryButton
          complementary={true}
          isFullWidth={true}
          label={t("back")}
          onClick={() => dispatch({ type: SeasonPassActionType.PREVIOUS_STEP })}
        />
      </div>
    </>
  );
};

const SelectCardsToReactivate = ({
  visitorCategories,
  reactivateQuantity,
  quantity,
  dispatch,
}: SelectCardsToReactivateProps) => {
  const { t } = useTranslation();

  const visitorCategoriesWithQuantity = visitorCategories
    .map((category) => ({
      ...category,
      quantity: quantity.get(category.category) ?? 0,
    }))
    .filter(({ quantity }) => quantity > 0);

  return (
    <div className={styles.selectCardsWrapper}>
      <h4 data-contentful-label-id="reactivateSelectQuantityHeading">{t("reactivateSelectQuantityHeading")}</h4>
      {visitorCategoriesWithQuantity.map(({ category, quantity, pricePerUnitText }) => {
        return (
          <QuantitySelectorStyled
            key={category}
            quantity={reactivateQuantity.get(category) ?? 0}
            minQuantity={0}
            maxQuantity={quantity}
            label={`${t("reactivate")}: ${t(`visitorCategory${category}`)}`}
            sublabel={pricePerUnitText}
            onQuantityChange={(newQuantity) => {
              dispatch({
                type: SeasonPassActionType.SET_QUANTITY_REACTIVATE,
                payload: { category, quantity: newQuantity },
              });
            }}
          />
        );
      })}
    </div>
  );
};

const SeasonPassReactivate = ({
  dispatch,
  visitorCategories,
  reactivateQuantity,
  quantity,
  reactivateDescription,
}: SeasonPassReactivateProps) => {
  const [showSelectReactivate, setShowSelectReactivate] = useState<boolean>(false);
  const { t } = useTranslation();

  useEffect(() => {
    if (isNonEmptyArray(reactivateQuantity)) {
      setShowSelectReactivate(true);
    }
  }, [reactivateQuantity]);

  const onClickNextStep = () => {
    dispatch({ type: SeasonPassActionType.SELECT_REACTIVATE_QUANTITY_COMPLETE });
  };
  return (
    <div className={styles.wrapper}>
      {reactivateDescription && (
        <div className={styles.introWrapper}>
          <RichText richText={reactivateDescription} />
        </div>
      )}
      {showSelectReactivate === false && (
        <ReactivateCardPrompt
          setShowSelectReactivate={setShowSelectReactivate}
          quantity={quantity}
          dispatch={dispatch}
        />
      )}
      {showSelectReactivate === true && (
        <>
          <SelectCardsToReactivate
            visitorCategories={visitorCategories}
            reactivateQuantity={reactivateQuantity}
            quantity={quantity}
            dispatch={dispatch}
          />
          <div className={`${styles.buttonWrapper} ${styles.margin}`}>
            <PrimaryButton
              complementary={true}
              label={t("back")}
              onClick={() => dispatch({ type: SeasonPassActionType.PREVIOUS_STEP })}
            />
            <PrimaryButton label={t("nextStep")} onClick={onClickNextStep} />
          </div>
        </>
      )}
    </div>
  );
};

export default SeasonPassReactivate;
